import sys; sys.path.insert(0,'.')
from cvlib import folds
d=np.load('base_reads.npz'); y=d['y']; R=np.load('reserved.npy')
keep=np.setdiff1d(np.arange(768),R)
M={j:d[f'mean_hidden_L{j}'][:,keep] for j in range(13)}
def z(X): return (X-X.mean(0))/(X.std(0)+1e-6)
def kcv(K, y, lams, seeds=(0,1,2)):
    Y=np.eye(8)[y]; out={}
    for lam in lams:
        a=[]
        for s in seeds:
            f=folds(y,5,s); S=np.zeros((len(y),8))
            for i in range(5):
                tr=f!=i; te=f==i
                A=np.linalg.solve(K[np.ix_(tr,tr)]+lam*np.eye(tr.sum()), Y[tr]-Y[tr].mean(0))
                S[te]=K[np.ix_(te,tr)]@A
            a.append((S.argmax(1)==y).mean())
        out[lam]=round(100*np.mean(a),2)
    return out
Zn={j:(lambda Z: Z/np.linalg.norm(Z,axis=1,keepdims=True))(z(M[j])) for j in range(13)}
Q={j:(Zn[j]@Zn[j].T) for j in (7,8,9)}
Lk={j:z(M[j])@z(M[j]).T/M[j].shape[1] for j in range(10)}
L=(1e-2,3e-2)
for top in (8,9):
    Kq=Q[top]+1.0*Q[top]**2
    for lins in [(2,),(2,5),(2,6),(3,6),(1,4,6),(2,4,6),(2,5,7),(1,3,5,7),(4,),(5,),(2,4),(3,5),(0,2,5)]:
        if max(lins)>=top: continue
        print(top,lins,kcv(Kq+sum(Lk[j] for j in lins),y,L))
